{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en niant une obligation de prestations de la Suva pour les douleurs au poignet gauche de la personne assurée.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le recours en matière de droit public peut être formé pour violation du droit au sens des art. 95 et 96 LTF.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Pour admettre un accident, la personne assurée doit rendre celui-ci vraisemblable au degré de la vraisemblance prépondérante; à défaut, il est réputé non survenu, au détriment de la personne assurée.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Pour se libérer de sa responsabilité en cas de lésion corporelle assimilée à un accident, l'assureur doit démontrer, au degré de la vraisemblance prépondérante, que la lésion est due à plus de 50 % à l'usure ou à une maladie.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que l'accident allégué n'est pas survenu avec une vraisemblance prépondérante.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale n'a pas violé le droit fédéral en accordant pleine valeur probante aux avis médicaux de la Suva et en retenant l'absence d'accident.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la Suva a réussi à apporter la preuve libératoire prévue à l'art. 6 al. 2 LAA, de sorte que le refus de prestations pour une lésion corporelle assimilée à un accident est conforme au droit fédéral.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le recours et confirme le jugement cantonal.",
      "b_propositions": ["P8"]
    }
  ]
}
